fn prime(n:i64)bool{if(n<2)return false;var d:i64=2;while(d*d<=n):(d+=1){if(@rem(n,d)==0)return false;}return true;}
fn mpow(a0:i64,e0:i64,m:i64)i64{var a=@rem(a0,m);var e=e0;var r:i64=1;while(e>0){if((e&1)!=0)r=@rem(r*a,m);a=@rem(a*a,m);e>>=1;}return r;}
export fn dsa_verify(v:?[*]const i64,n:usize)i64{if(n<7 or n>15)return -1;const a=v orelse return -1;const p=a[0];const q=a[1];const g=a[2];const y=a[3];const r=a[4];const s=a[5];const ml=a[6];if(ml<0 or ml>8 or n!=7+@as(usize,@intCast(ml)))return -1;if(p<5 or p>251 or !prime(p) or q<2 or q>=p or @rem(p-1,q)!=0 or !prime(q))return -1;if(g<2 or g>=p or mpow(g,q,p)!=1 or y<1 or y>=p or mpow(y,q,p)!=1 or r<1 or r>=q or s<1 or s>=q)return -1;var h:i64=0;for(0..@intCast(ml))|i|{if(a[7+i]<0 or a[7+i]>255)return -1;h=@rem(h*256+a[7+i],q);}const w=mpow(s,q-2,q);const exp1=@rem(h*w,q);const exp2=@rem(r*w,q);return if(@rem(@rem(mpow(g,exp1,p)*mpow(y,exp2,p),p),q)==r)1 else 0;}
